//             return;
//         }
//         dfs(root->right, k, cur);
//     }
// };

class Solution {
public:
    // 用栈来迭代
    int kthSmallest(TreeNode* root, int k) {
        stack<TreeNode*> stk;
        TreeNode* cur = root;
        int cnt = 0;

        while (cur || !stk.empty()) {
            while (cur) {
                // 一直向左走
                stk.push(cur);
                cur = cur->left;
            }
            // 弹出最左边的节点
            cur = stk.top();
            stk.pop();
            // 访问当前节点
            cnt++;
            if (cnt == k)
                return cur->val;

            // 访问当前节点的右子树
            cur = cur->right;
        }
        return -1;
    }
};
```

