# 13. 综合示例

同时执行三个任务：

```cpp
#include <iostream>
#include <future>
#include <thread>
#include <chrono>

using namespace std;

string query(string name, int seconds) {
    cout << name << " start" << endl;

    this_thread::sleep_for(
        chrono::seconds(seconds)
    );

    return name + " finished";
}

int main() {
    future<string> f1 =
        async(launch::async, query, "task A", 3);

    future<string> f2 =
        async(launch::async, query, "task B", 1);

    future<string> f3 =
        async(launch::async, query, "task C", 2);

    cout << f1.get() << endl;
    cout << f2.get() << endl;
    cout << f3.get() << endl;

    return 0;
}
```

三个异步任务可以同时运行。

