```cpp
//双指针版本
int partsort2(int* a, int left, int right)
{
	int x = Midofthree(a, left, right, (right + left) / 2);
	Swap(&a[x], &a[left]);
	int keyi = left;
	int prev = left;
	int cur = prev + 1;
	while (cur <= right)
	{
		if (a[cur] < a[keyi] && ++prev != cur)
			Swap(&a[cur], &a[prev]);

		cur++;
	}
	Swap(&a[prev],&a[keyi]);
	return prev;
}
```

