int partsort3(int* a, int left, int right)
{
	int x = Midofthree(a, left, right, (right + left) / 2);
	Swap(&a[x], &a[left]);
	int key = a[left];
	int pit = left;
	int begin = left;
	int end = right;
	while (begin < end)
	{
		while (a[end] >= key && begin < end)
			end--;

		a[pit] = a[end];
		pit = end;

		while (a[begin] <= key && begin < end)
			begin++;

		a[pit] = a[begin];
		pit = begin;
	}
	a[pit] = key;
	return pit;
}
