```cpp
void QuickSortNonR(int* a, int left, int right)
{
	ST s;
	STInit(&s);
	STPush(&s, right);
	STPush(&s, left);

 	while (!STEmpty(&s))
	{
		int begin = STTop(&s);
		STPop(&s);
		int end = STTop(&s);
		STPop(&s);

		int mid = partsort1(a, begin, end);
		if (mid + 1 < end)//注意这里需判断
		{
			STPush(&s, end);
			STPush(&s, mid + 1);
		}
		if (begin < mid - 1)//注意这里需判断
		{
			STPush(&s, mid - 1);
			STPush(&s, begin);
		}
	}
}
```

