//模拟实现memmove
void* my_memmove(void* dest,void* sour,size_t num)
{
	assert(dest && sour);
	char* tmp = (char*)dest;
	if (dest == sour)
		return dest;
	else if (dest < sour)
	{
		while (num--)
		{
			*(((char*)dest)++) = *(((char*)sour)++);
		}
	}
	else
	{
		while (num--)
		{
			*(((char*) dest) + num) = *(((char*) sour) + num);
		}
	}
	return tmp;
}
