```cpp
#include <stdio.h>
int x = 1;
int fun(int k)
{
	int sum = 0;
	while (k>x)
	{
		sum += x * x;
		k -= x;
		x++;
	}
	sum += k * x;
	return sum;
}
int main()
{
	int k = 0;
	scanf("%d",&k);
	int ret = fun(k);
	printf("%d\n", ret);
}
